def max_depth(root):
    if root is None:
        return 0
    return 1 + max((max_depth(c) for c in root.children), default=0)

def max_depth(root):
    depth, level = 0, [root] if root else []
    while level:
        depth += 1
        level = [c for node in level for c in node.children]
    return depth
